import{_ as e,o as i,c as l,O as o}from"./chunks/framework.db831a78.js";const p=JSON.parse('{"title":"Spring 全家桶","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/04-Spring全家桶.md","filePath":"interview/后端/Java/04-Spring全家桶.md","lastUpdated":null}'),r={name:"interview/后端/Java/04-Spring全家桶.md"};function t(n,a,s,h,c,d){return i(),l("div",null,a[0]||(a[0]=[o('<h1 id="spring-全家桶" tabindex="-1">Spring 全家桶 <a class="header-anchor" href="#spring-全家桶" aria-label="Permalink to &quot;Spring 全家桶&quot;">​</a></h1><blockquote><p>常问等级：★★★ 高频必考 / ★★☆ 中频常见 / ★☆☆ 低频了解 深度标准：每个考点讲清「是什么 → 为什么 → 源码关键点 → 追问应对 → 易错点」。</p></blockquote><hr><h2 id="ioc-控制反转与-di-依赖注入-★★★" tabindex="-1">IOC 控制反转与 DI 依赖注入 ★★★ <a class="header-anchor" href="#ioc-控制反转与-di-依赖注入-★★★" aria-label="Permalink to &quot;IOC 控制反转与 DI 依赖注入 ★★★&quot;">​</a></h2><h3 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><ul><li>IOC（控制反转）：把「对象创建和依赖管理」的控制权从业务代码反转给 Spring 容器，容器负责创建 Bean 并注入依赖。</li><li>DI（依赖注入）：IOC 的具体实现方式，通过构造器/setter/字段把依赖注入。</li></ul><h3 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h3><ul><li>解耦：对象不再自己 new 依赖，改依赖只需改配置/注解，符合开闭原则；便于测试（可注入 mock）。</li></ul><h3 id="依赖注入方式" tabindex="-1">依赖注入方式 <a class="header-anchor" href="#依赖注入方式" aria-label="Permalink to &quot;依赖注入方式&quot;">​</a></h3><ul><li>构造器注入（推荐：依赖不可变、避免循环依赖更明显、便于测试）、setter 注入、字段注入（@Autowired 反射，不推荐——难测试、隐藏依赖）。</li></ul><h3 id="追问应对" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「IOC 和 DI 是同一个东西吗？」→ IOC 是思想，DI 是实现手段，两者常一起说。</li><li>「BeanFactory 和 ApplicationContext 区别？」→ 见下文。</li></ul><hr><h2 id="beanfactory-与-applicationcontext-区别-★★☆" tabindex="-1">BeanFactory 与 ApplicationContext 区别 ★★☆ <a class="header-anchor" href="#beanfactory-与-applicationcontext-区别-★★☆" aria-label="Permalink to &quot;BeanFactory 与 ApplicationContext 区别 ★★☆&quot;">​</a></h2><ul><li>BeanFactory：IOC 容器最底层接口，懒加载（getBean 时才创建），功能少。</li><li>ApplicationContext：继承 BeanFactory，启动时预实例化所有单例 Bean（饿加载）、提供国际化、事件发布、资源加载、AOP 等扩展。</li><li>生产中都用 ApplicationContext（SpringBoot 内置）。</li></ul><hr><h2 id="bean-生命周期-★★★" tabindex="-1">Bean 生命周期 ★★★ <a class="header-anchor" href="#bean-生命周期-★★★" aria-label="Permalink to &quot;Bean 生命周期 ★★★&quot;">​</a></h2><h3 id="完整流程" tabindex="-1">完整流程 <a class="header-anchor" href="#完整流程" aria-label="Permalink to &quot;完整流程&quot;">​</a></h3><ol><li>实例化：反射调用构造器创建对象。</li><li>属性注入：populateBean 填充依赖。</li><li>Aware 接口：BeanNameAware、BeanFactoryAware、ApplicationContextAware 等。</li><li>BeanPostProcessor 前置处理：<code>postProcessBeforeInitialization</code>。</li><li>初始化：@PostConstruct → InitializingBean 的 afterPropertiesSet → 自定义 init-method。</li><li>BeanPostProcessor 后置处理：<code>postProcessAfterInitialization</code>（AOP 在此生成代理）。</li><li>使用。</li><li>销毁：@PreDestroy → DisposableBean 的 destroy → 自定义 destroy-method。</li></ol><h3 id="追问应对-1" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-1" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「@PostConstruct 和 afterPropertiesSet 哪个先执行？」→ @PostConstruct 先（由 CommonAnnotationBeanPostProcessor 处理），afterPropertiesSet 后。</li><li>「AOP 代理在哪一步生成？」→ BeanPostProcessor 的 postProcessAfterInitialization。</li></ul><hr><h2 id="bean-作用域-★★☆" tabindex="-1">Bean 作用域 ★★☆ <a class="header-anchor" href="#bean-作用域-★★☆" aria-label="Permalink to &quot;Bean 作用域 ★★☆&quot;">​</a></h2><ul><li>singleton：单例（默认），容器一个实例。</li><li>prototype：每次获取新建实例。</li><li>request / session / application：Web 环境，一次请求/会话/应用一个实例。</li><li>注意：prototype Bean 注入到 singleton Bean 时，只会注入一次，不会每次新实例（需用 <code>@Lookup</code> 或注入 ObjectFactory 解决）。</li></ul><h3 id="追问应对-2" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-2" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「prototype 和 singleton 怎么选？」→ 无状态用 singleton；有状态（每个请求独立数据）用 prototype，但需注意注入到单例的坑。</li></ul><hr><h2 id="spring-单例-bean-线程安全问题-★★★" tabindex="-1">Spring 单例 Bean 线程安全问题 ★★★ <a class="header-anchor" href="#spring-单例-bean-线程安全问题-★★★" aria-label="Permalink to &quot;Spring 单例 Bean 线程安全问题 ★★★&quot;">​</a></h2><ul><li>单例 Bean 本身是无状态（只有方法、无共享可变字段）→ 线程安全。</li><li>若有共享可变成员变量（如计数器、缓存），多线程访问会出问题。</li><li>解决：① 尽量无状态；② 用 ThreadLocal 隔离；③ 用并发容器/原子类；④ 改 prototype。</li></ul><h3 id="追问应对-3" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-3" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「Controller 是线程安全的吗？」→ Controller 默认单例，若不在其中定义可变成员变量就是线程安全的；局部变量安全。</li></ul><hr><h2 id="spring-三级缓存解决循环依赖-★★★" tabindex="-1">Spring 三级缓存解决循环依赖 ★★★ <a class="header-anchor" href="#spring-三级缓存解决循环依赖-★★★" aria-label="Permalink to &quot;Spring 三级缓存解决循环依赖 ★★★&quot;">​</a></h2><h3 id="三级缓存" tabindex="-1">三级缓存 <a class="header-anchor" href="#三级缓存" aria-label="Permalink to &quot;三级缓存&quot;">​</a></h3><ul><li>一级缓存 singletonObjects：完整 Bean。</li><li>二级缓存 earlySingletonObjects：早期暴露的 Bean（未完成初始化）。</li><li>三级缓存 singletonFactories：ObjectFactory，可提前暴露 Bean 的工厂（配合 AOP 返回代理）。</li></ul><h3 id="解决流程-a-依赖-b-b-依赖-a" tabindex="-1">解决流程（A 依赖 B，B 依赖 A） <a class="header-anchor" href="#解决流程-a-依赖-b-b-依赖-a" aria-label="Permalink to &quot;解决流程（A 依赖 B，B 依赖 A）&quot;">​</a></h3><ol><li>创建 A，实例化后把 A 的 ObjectFactory 放入三级缓存。</li><li>A 注入 B → 创建 B，B 注入 A → 从三级缓存拿到 A 的早期引用，放入二级缓存。</li><li>B 完成，A 完成，最终 A 放入一级缓存。</li></ol><h3 id="关键限制" tabindex="-1">关键限制 <a class="header-anchor" href="#关键限制" aria-label="Permalink to &quot;关键限制&quot;">​</a></h3><ul><li>只能解决「单例 + setter/字段注入」的循环依赖；构造器注入循环依赖无法解决（抛 BeanCurrentlyInCreationException）。</li><li>加了 <code>@Async</code>、AOP 代理等可能影响早期引用。</li></ul><h3 id="追问应对-4" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-4" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么需要二级缓存？」→ 避免同一 Bean 多次从工厂生成早期对象（保证早期引用唯一，尤其 AOP 代理对象要一致）。</li><li>「构造器循环依赖为什么解决不了？」→ 构造器注入要求创建时立即拿到依赖，此时依赖还没实例化，无从注入。</li></ul><hr><h2 id="aop-原理-jdk-动态代理-vs-cglib-★★★" tabindex="-1">AOP 原理（JDK 动态代理 vs CGLIB）★★★ <a class="header-anchor" href="#aop-原理-jdk-动态代理-vs-cglib-★★★" aria-label="Permalink to &quot;AOP 原理（JDK 动态代理 vs CGLIB）★★★&quot;">​</a></h2><h3 id="是什么-1" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-1" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><ul><li>AOP：面向切面编程，把横切关注点（日志、事务、权限）与业务逻辑分离。</li><li>术语：切面（Aspect）、连接点（JoinPoint）、切入点（Pointcut）、通知（Advice：before/after/around/afterReturning/afterThrowing）。</li></ul><h3 id="实现" tabindex="-1">实现 <a class="header-anchor" href="#实现" aria-label="Permalink to &quot;实现&quot;">​</a></h3><ul><li>JDK 动态代理：基于接口，<code>Proxy.newProxyInstance</code> + InvocationHandler，要求目标类实现接口。</li><li>CGLIB：基于继承，生成目标类子类，通过 ASM 字节码，无需接口；不能代理 final 类/方法。</li><li>Spring 默认：目标有接口用 JDK 代理，无接口用 CGLIB；SpringBoot 默认（proxyTargetClass=true）直接 CGLIB。</li></ul><h3 id="追问应对-5" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-5" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「JDK 动态代理和 CGLIB 区别？」→ JDK 基于接口反射、只能代理接口；CGLIB 基于继承字节码、可代理普通类，但 final 不行、性能略高。</li><li>「AOP 失效场景？」→ 见下文。</li></ul><hr><h2 id="transactional-失效场景-高频必考-★★★" tabindex="-1">@Transactional 失效场景（高频必考）★★★ <a class="header-anchor" href="#transactional-失效场景-高频必考-★★★" aria-label="Permalink to &quot;@Transactional 失效场景（高频必考）★★★&quot;">​</a></h2><h3 id="常见失效" tabindex="-1">常见失效 <a class="header-anchor" href="#常见失效" aria-label="Permalink to &quot;常见失效&quot;">​</a></h3><ol><li>非 public 方法（Spring 事务基于代理，只对 public 生效）。</li><li>同类方法自调用（<code>this.xxx()</code> 不经过代理，事务不生效）。</li><li>异常被 catch 吞掉（不抛异常，事务不感知）。</li><li>抛出受检异常（默认只对 RuntimeException/Error 回滚；需 <code>rollbackFor = Exception.class</code>）。</li><li>传播行为设置不当（如 PROPAGATION_NOT_SUPPORTED 挂起事务）。</li><li>方法不是被 Spring 管理的 Bean（如普通类 new 出来的）。</li><li>数据库引擎不支持事务（MyISAM）。</li></ol><h3 id="追问应对-6" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-6" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「自调用为什么失效？怎么解决？」→ this 调用绕过代理对象；解决：注入自身、<code>AopContext.currentProxy()</code>（需 exposeProxy=true）、抽到另一个 Bean。</li><li>「为什么默认只回滚 RuntimeException？」→ 设计约定，受检异常通常由业务处理，不默认回滚。</li></ul><hr><h2 id="spring-事务传播行为-★★★" tabindex="-1">Spring 事务传播行为 ★★★ <a class="header-anchor" href="#spring-事务传播行为-★★★" aria-label="Permalink to &quot;Spring 事务传播行为 ★★★&quot;">​</a></h2><ul><li>REQUIRED（默认）：有事务则加入，无则新建。</li><li>REQUIRES_NEW：总是新建事务，挂起当前事务（互不影响）。</li><li>SUPPORTS：有则加入，无则非事务运行。</li><li>NOT_SUPPORTED：非事务运行，挂起当前事务。</li><li>MANDATORY：必须有事务，否则抛异常。</li><li>NEVER：必须无事务，有则抛异常。</li><li>NESTED：嵌套事务（内层回滚不影响外层，依赖 savepoint）。</li></ul><h3 id="追问应对-7" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-7" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「REQUIRED 和 REQUIRES_NEW 区别？」→ REQUIRED 共用同一事务，一个回滚全回滚；REQUIRES_NEW 独立事务，内层回滚不影响外层。</li></ul><hr><h2 id="spring-boot-自动配置原理-前端转全栈必考-★★★" tabindex="-1">Spring Boot 自动配置原理（前端转全栈必考）★★★ <a class="header-anchor" href="#spring-boot-自动配置原理-前端转全栈必考-★★★" aria-label="Permalink to &quot;Spring Boot 自动配置原理（前端转全栈必考）★★★&quot;">​</a></h2><h3 id="核心" tabindex="-1">核心 <a class="header-anchor" href="#核心" aria-label="Permalink to &quot;核心&quot;">​</a></h3><ul><li>启动类 <code>@SpringBootApplication</code> = <code>@SpringBootConfiguration + @EnableAutoConfiguration + @ComponentScan</code>。</li><li><code>@EnableAutoConfiguration</code> → <code>@Import(AutoConfigurationImportSelector)</code>。</li><li>读取 <code>META-INF/spring.factories</code>（或新版的 <code>AutoConfiguration.imports</code>）里注册的自动配置类。</li><li>每个自动配置类用 <code>@ConditionalOnClass</code>（类存在）、<code>@ConditionalOnMissingBean</code>（Bean 不存在）、<code>@ConditionalOnProperty</code>（配置满足）等条件注解判断是否生效。</li><li>配合 <code>spring-boot-autoconfigure</code> 提供大量默认配置，实现「约定大于配置」。</li></ul><h3 id="追问应对-8" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-8" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「自定义一个 starter 怎么做？」→ 写一个配置类 + <code>META-INF/spring.factories</code> 注册 + 条件注解 + properties 类，让使用者引入依赖即自动配置。</li></ul><hr><h2 id="springmvc-请求处理流程-★★★" tabindex="-1">SpringMVC 请求处理流程 ★★★ <a class="header-anchor" href="#springmvc-请求处理流程-★★★" aria-label="Permalink to &quot;SpringMVC 请求处理流程 ★★★&quot;">​</a></h2><ol><li>请求到达 DispatcherServlet（前端控制器）。</li><li>HandlerMapping 根据 URL 找 Handler（Controller + 方法）。</li><li>HandlerAdapter 执行 Handler，参数解析、转换、校验。</li><li>返回 ModelAndView 或 @ResponseBody 直接写响应。</li><li>ViewResolver 解析视图（或直接返回 JSON）。</li><li>响应返回客户端。</li></ol><h3 id="追问应对-9" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-9" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「@RequestBody 和 @RequestParam 区别？」→ @RequestBody 读请求体（JSON→对象，走 HttpMessageConverter）；@RequestParam 取 URL 参数/表单字段。</li></ul><hr><h2 id="bean-装配注解区别-★★☆" tabindex="-1">Bean 装配注解区别 ★★☆ <a class="header-anchor" href="#bean-装配注解区别-★★☆" aria-label="Permalink to &quot;Bean 装配注解区别 ★★☆&quot;">​</a></h2><ul><li>@Autowired：按类型注入，配合 @Qualifier 按名称；required=false 可空。</li><li>@Resource：JDK 注解，默认按名称，找不到再按类型。</li><li>@Inject：JSR-330，类似 @Autowired。</li><li>区别：@Autowired 是 Spring 的，@Resource 是 Java 标准的。</li></ul><hr><h2 id="spring、springboot、springcloud-区别-前端转全栈必考-★★★" tabindex="-1">Spring、SpringBoot、SpringCloud 区别（前端转全栈必考）★★★ <a class="header-anchor" href="#spring、springboot、springcloud-区别-前端转全栈必考-★★★" aria-label="Permalink to &quot;Spring、SpringBoot、SpringCloud 区别（前端转全栈必考）★★★&quot;">​</a></h2><ul><li>Spring：核心框架，提供 IOC 与 AOP，配置繁琐。</li><li>SpringBoot：对 Spring 的封装增强，自动配置 + 起步依赖 + 内嵌服务器，快速搭建。</li><li>SpringCloud：基于 SpringBoot 的微服务工具集（注册中心、配置中心、网关、服务调用、熔断）。</li><li>一句话：Spring 是地基，SpringBoot 快速建房，SpringCloud 城市基础设施。</li></ul><hr><h2 id="spring-security-鉴权链路-jwt-过滤器链-★★★" tabindex="-1">Spring Security 鉴权链路（JWT 过滤器链）★★★ <a class="header-anchor" href="#spring-security-鉴权链路-jwt-过滤器链-★★★" aria-label="Permalink to &quot;Spring Security 鉴权链路（JWT 过滤器链）★★★&quot;">​</a></h2><h3 id="核心思想" tabindex="-1">核心思想 <a class="header-anchor" href="#核心思想" aria-label="Permalink to &quot;核心思想&quot;">​</a></h3><ul><li>基于「过滤器链（Filter Chain）」，请求先经过认证（Authentication）与授权（Authorization）的过滤器，再进入业务 Controller。</li></ul><h3 id="认证流程" tabindex="-1">认证流程 <a class="header-anchor" href="#认证流程" aria-label="Permalink to &quot;认证流程&quot;">​</a></h3><ol><li>请求携带 Token（JWT）。</li><li>自定义 JWT 过滤器解析 Token，校验签名与有效期。</li><li>取出用户信息，构造 Authentication 放入 <code>SecurityContextHolder</code>。</li><li>后续授权判断基于 SecurityContext 里的用户角色/权限。</li></ol><h3 id="授权" tabindex="-1">授权 <a class="header-anchor" href="#授权" aria-label="Permalink to &quot;授权&quot;">​</a></h3><ul><li><code>@PreAuthorize(&quot;hasRole(&#39;ADMIN&#39;)&quot;)</code> 方法级；<code>antMatchers(...).hasAuthority(...)</code> URL 级。</li><li><code>UserDetailsService</code> 加载用户、<code>AuthenticationManager</code> 校验。</li></ul><h3 id="jwt-结构" tabindex="-1">JWT 结构 <a class="header-anchor" href="#jwt-结构" aria-label="Permalink to &quot;JWT 结构&quot;">​</a></h3><ul><li>Header.Payload.Signature 三段 Base64；Payload 存用户 id/角色（不放敏感信息），Signature 用密钥签名防篡改。</li></ul><h3 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h3><ul><li>JWT 无状态、无法主动踢下线（配合 Redis 黑名单/刷新 token）。</li><li>过滤器顺序（JWT 过滤器要在 UsernamePasswordAuthenticationFilter 之前）。</li><li>放行白名单（登录接口、静态资源）。</li></ul><hr><h2 id="mybatis-一级缓存、二级缓存-★★★" tabindex="-1">MyBatis 一级缓存、二级缓存 ★★★ <a class="header-anchor" href="#mybatis-一级缓存、二级缓存-★★★" aria-label="Permalink to &quot;MyBatis 一级缓存、二级缓存 ★★★&quot;">​</a></h2><h3 id="一级缓存" tabindex="-1">一级缓存 <a class="header-anchor" href="#一级缓存" aria-label="Permalink to &quot;一级缓存&quot;">​</a></h3><ul><li>SqlSession 级别，默认开启；同一 SqlSession 内相同查询走缓存，不同 SqlSession 不共享。</li><li>SqlSession 关闭或执行增删改/commit 时清空；可能「先查后改再查」读到脏缓存。</li></ul><h3 id="二级缓存" tabindex="-1">二级缓存 <a class="header-anchor" href="#二级缓存" aria-label="Permalink to &quot;二级缓存&quot;">​</a></h3><ul><li>Mapper（namespace）级别，跨 SqlSession 共享；需显式开启（<code>cacheEnabled=true</code> + mapper 加 <code>&lt;cache/&gt;</code>），实体需序列化。</li><li>分布式下可能读到旧数据，实际线上多关闭或慎用。</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><ul><li>MyBatis 缓存粒度粗，业务里更常用 Redis 做缓存；一二级缓存仅在单机、读多写少且一致性要求不高时用。</li></ul><hr><h2 id="mybatis-执行流程-★★☆" tabindex="-1">MyBatis 执行流程 ★★☆ <a class="header-anchor" href="#mybatis-执行流程-★★☆" aria-label="Permalink to &quot;MyBatis 执行流程 ★★☆&quot;">​</a></h2><ol><li>配置加载：解析 mybatis-config.xml 与 Mapper XML/注解，生成 Configuration 与 MappedStatement。</li><li>获取 SqlSession：SqlSessionFactory.openSession()，内部创建 Executor。</li><li>执行：Mapper 接口动态代理 → 找 MappedStatement → Executor 执行 → StatementHandler 处理参数与结果映射 → ResultSetHandler 映射为 POJO。</li><li>插件：Interceptor 动态代理拦截 ParameterHandler/ResultSetHandler/StatementHandler/Executor（分页插件基于此）。</li></ol><hr><h2 id="mybatis-plus-相比-mybatis-的优势-★★☆" tabindex="-1">MyBatis-Plus 相比 MyBatis 的优势 ★★☆ <a class="header-anchor" href="#mybatis-plus-相比-mybatis-的优势-★★☆" aria-label="Permalink to &quot;MyBatis-Plus 相比 MyBatis 的优势 ★★☆&quot;">​</a></h2><ul><li>内置通用 CRUD（BaseMapper）、条件构造器（Wrapper）、分页插件、逻辑删除、自动填充、代码生成器，减少样板 SQL；本质仍是 MyBatis 增强，不改变底层。</li></ul><hr><h2 id="mybatis-和-区别-必考-★★★" tabindex="-1">MyBatis #{} 和 ${} 区别（必考）★★★ <a class="header-anchor" href="#mybatis-和-区别-必考-★★★" aria-label="Permalink to &quot;MyBatis #{} 和 ${} 区别（必考）★★★&quot;">​</a></h2><ul><li><code>#{}</code>：预编译占位符（PreparedStatement 的 ?），自动加引号、防 SQL 注入。</li><li><code>${}</code>：字符串拼接，直接替换，不防注入，仅用于表名/列名等不能预编译的场景（如 <code>ORDER BY ${column}</code>，且需白名单校验）。</li><li>结论：能用 <code>#{}</code> 绝不用 <code>${}</code>。</li></ul><h3 id="追问应对-10" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-10" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么 #{} 能防注入？」→ 预编译把 SQL 结构与参数分离，参数按值绑定，不会被当作 SQL 关键字执行。</li></ul><hr><h2 id="spring-中常用设计模式-★★★" tabindex="-1">Spring 中常用设计模式 ★★★ <a class="header-anchor" href="#spring-中常用设计模式-★★★" aria-label="Permalink to &quot;Spring 中常用设计模式 ★★★&quot;">​</a></h2><ul><li>工厂模式：BeanFactory/ApplicationContext。</li><li>单例模式：默认 Bean 作用域。</li><li>代理模式：AOP。</li><li>模板方法：JdbcTemplate、RestTemplate。</li><li>观察者模式：ApplicationEvent 事件机制。</li><li>适配器模式：HandlerAdapter、MethodArgumentResolver。</li><li>装饰器/策略：各种 Wrapper、资源处理。</li></ul><h3 id="追问应对-11" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-11" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「Spring 用代理模式干什么？」→ AOP 生成代理对象，在方法前后织入切面逻辑（事务、日志）。</li></ul><hr><h2 id="spring-循环依赖、三级缓存、-async-失效-★★★" tabindex="-1">Spring 循环依赖、三级缓存、@Async 失效 ★★★ <a class="header-anchor" href="#spring-循环依赖、三级缓存、-async-失效-★★★" aria-label="Permalink to &quot;Spring 循环依赖、三级缓存、@Async 失效 ★★★&quot;">​</a></h2><ul><li>循环依赖与三级缓存：见上文。</li><li>@Async 失效原因：同类自调用（this 方法调用不经过代理）、方法非 public、Bean 未被 Spring 管理、未开启 <code>@EnableAsync</code>。</li><li>解决：抽到另一 Bean、注入自身、<code>AopContext.currentProxy()</code>。</li></ul><hr><h2 id="springmvc-参数校验、全局异常处理-★★☆" tabindex="-1">SpringMVC 参数校验、全局异常处理 ★★☆ <a class="header-anchor" href="#springmvc-参数校验、全局异常处理-★★☆" aria-label="Permalink to &quot;SpringMVC 参数校验、全局异常处理 ★★☆&quot;">​</a></h2><ul><li>参数校验：@Valid/@Validated + @NotNull/@NotBlank/@Size 等，配合 BindingResult 或全局异常处理器。</li><li>全局异常：<code>@RestControllerAdvice</code> + <code>@ExceptionHandler</code>，统一返回错误结构。</li><li>@ControllerAdvice 处理 Controller 异常，@RestControllerAdvice 是它的 @ResponseBody 版本。</li></ul><hr><h2 id="spring-cloud-核心组件-★★★" tabindex="-1">Spring Cloud 核心组件 ★★★ <a class="header-anchor" href="#spring-cloud-核心组件-★★★" aria-label="Permalink to &quot;Spring Cloud 核心组件 ★★★&quot;">​</a></h2><ul><li>注册中心：Nacos / Eureka（服务发现与注册）。</li><li>配置中心：Nacos Config / Spring Cloud Config。</li><li>网关：Spring Cloud Gateway（路由、过滤、限流）。</li><li>服务调用：OpenFeign（声明式 HTTP 客户端）。</li><li>熔断限流：Sentinel / Resilience4j / Hystrix。</li><li>负载均衡：Ribbon / LoadBalancer。</li><li>链路追踪：Sleuth + Zipkin（或 Micrometer + SkyWalking）。</li></ul><h3 id="追问应对-12" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-12" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「Feign 和 RestTemplate 区别？」→ Feign 声明式接口、自动负载均衡、简洁；RestTemplate 需手动拼接 URL。</li><li>「Nacos 和 Eureka 区别？」→ Nacos 支持服务发现 + 配置中心一体，支持 CP/AP 切换；Eureka 只做服务发现、AP。</li></ul><hr><h2 id="网关作用、gateway-过滤器-★★☆" tabindex="-1">网关作用、Gateway 过滤器 ★★☆ <a class="header-anchor" href="#网关作用、gateway-过滤器-★★☆" aria-label="Permalink to &quot;网关作用、Gateway 过滤器 ★★☆&quot;">​</a></h2><ul><li>网关作用：统一入口、路由转发、鉴权、限流、日志、灰度。</li><li>Gateway 基于 WebFlux（响应式）、非阻塞；过滤器分全局 GlobalFilter 和局部 GatewayFilter。</li><li>断言（Predicate）：按路径、方法、header 等匹配路由。</li></ul><hr><h2 id="微服务架构的优缺点-★★☆" tabindex="-1">微服务架构的优缺点 ★★☆ <a class="header-anchor" href="#微服务架构的优缺点-★★☆" aria-label="Permalink to &quot;微服务架构的优缺点 ★★☆&quot;">​</a></h2><ul><li>优点：独立部署、技术栈灵活、故障隔离、可扩展性强。</li><li>缺点：分布式复杂度（事务、一致性、网络）、运维成本高、服务治理难、调试/链路复杂。</li><li>适合：业务复杂、团队大、需独立扩展；小项目不必强行微服务。</li></ul>',130)]))}const b=e(r,[["render",t]]);export{p as __pageData,b as default};
